  {
    id: "q1",
    number: "01",
    tag: "Origins",
    text: "Which of the following are statically typed programming languages?",
    helpText: "Select all that apply — some questions may have more than one correct answer.",
    choices: [
      { id: "q1a", label: "TypeScript" },
      { id: "q1b", label: "Python" },
      { id: "q1c", label: "Rust" },
      { id: "q1d", label: "Ruby" },
    ],
    correct: ["q1a", "q1c"],
  },
  {
    id: "q2",
    number: "02",
    tag: "Paradigms",
    text: "Which languages primarily support functional programming as a first-class paradigm?",
    choices: [
      { id: "q2a", label: "Haskell" },
      { id: "q2b", label: "Java" },
      { id: "q2c", label: "Elixir" },
      { id: "q2d", label: "C" },
    ],
    correct: ["q2a", "q2c"],
  },
  {
    id: "q3",
    number: "03",
    tag: "History",
    text: "Which of the following languages were created in the 1970s?",
    choices: [
      { id: "q3a", label: "C" },
      { id: "q3b", label: "JavaScript" },
      { id: "q3c", label: "Smalltalk" },
      { id: "q3d", label: "Go" },
    ],
    correct: ["q3a", "q3c"],
  },
];

// ─── State ───────────────────────────────────────────────────────────────────
const state = {
  selections: { q1: new Set(), q2: new Set(), q3: new Set() },
  submitted: false,
};

// ─── Helpers ──────────────────────────────────────────────────────────────────
function arraysMatch(a, b) {
  return a.length === b.length && a.every((v) => b.includes(v));
}

function updateProgress() {
  const answered = QUESTIONS.filter((q) => state.selections[q.id].size > 0).length;
  const pct = (answered / QUESTIONS.length) * 100;
  document.querySelector(".progress-bar-fill").style.width = pct + "%";
}

// ─── Render ───────────────────────────────────────────────────────────────────
function renderQuestion(q) {
  const fieldEl = document.createElement("div");
  fieldEl.className = "form-field";
  fieldEl.setAttribute("role", "group");
  fieldEl.setAttribute("aria-labelledby", `${q.id}-label`);

  const meta = document.createElement("div");
  meta.className = "question-meta";
  meta.innerHTML = `<span class="question-number">${q.number}</span><span class="question-tag">${q.tag}</span>`;

  const questionText = document.createElement("p");
  questionText.className = "question-text";
  questionText.id = `${q.id}-label`;
  questionText.textContent = q.text;

  fieldEl.appendChild(meta);
  fieldEl.appendChild(questionText);

  if (q.helpText) {
    const help = document.createElement("p");
    help.className = "help-text";
    help.id = `${q.id}-help`;
    help.textContent = q.helpText;
    fieldEl.appendChild(help);
    fieldEl.setAttribute("aria-describedby", `${q.id}-help`);
  }

  const choiceList = document.createElement("div");
  choiceList.className = "choices";
  choiceList.setAttribute("role", "group");

  q.choices.forEach((choice) => {
    const label = document.createElement("label");
    label.className = "choice-label";
    label.htmlFor = choice.id;

    const checkbox = document.createElement("input");
    checkbox.type = "checkbox";
    checkbox.className = "choice-checkbox";
    checkbox.id = choice.id;
    checkbox.name = q.id;
    checkbox.value = choice.id;
    checkbox.setAttribute("aria-label", choice.label);

    checkbox.addEventListener("change", () => {
      if (state.submitted) return;
      if (checkbox.checked) {
        state.selections[q.id].add(choice.id);
      } else {
        state.selections[q.id].delete(choice.id);
      }
      updateProgress();
    });

    const text = document.createElement("span");
    text.className = "choice-text";
    text.textContent = choice.label;

    label.appendChild(checkbox);
    label.appendChild(text);
    choiceList.appendChild(label);
  });

  fieldEl.appendChild(choiceList);
  return fieldEl;
}

function renderForm() {
  const form = document.querySelector(".quiz-form");
  const questionContainer = document.getElementById("question-container");
  questionContainer.innerHTML = "";

  QUESTIONS.forEach((q) => {
    questionContainer.appendChild(renderQuestion(q));
  });
}

// ─── Score ────────────────────────────────────────────────────────────────────
function gradeQuiz() {
  let score = 0;
  QUESTIONS.forEach((q) => {
    const selected = Array.from(state.selections[q.id]);
    const isCorrect = arraysMatch(selected, q.correct);
    if (isCorrect) score++;

    const field = document.querySelector(`[aria-labelledby="${q.id}-label"]`);
    field.classList.add(isCorrect ? "correct" : "incorrect");

    // Disable all checkboxes
    field.querySelectorAll("input[type=checkbox]").forEach((cb) => {
      cb.disabled = true;
    });

    // Show feedback badge
    const badge = document.createElement("div");
    badge.className = `feedback-badge ${isCorrect ? "correct" : "incorrect"}`;
    badge.setAttribute("role", "status");
    badge.setAttribute("aria-live", "polite");
    badge.innerHTML = isCorrect
      ? `<span aria-hidden="true">✓</span> Correct`
      : `<span aria-hidden="true">✗</span> Incorrect — correct: ${q.correct.map((id) => q.choices.find((c) => c.id === id).label).join(" & ")}`;
    field.appendChild(badge);
  });
  return score;
}

function showResult(score) {
  const panel = document.getElementById("result-panel");
  const emoji = panel.querySelector(".result-emoji");
  const title = panel.querySelector(".result-title");
  const message = panel.querySelector(".result-message");
  const scoreNum = panel.querySelector(".score-number");

  scoreNum.textContent = `${score}/${QUESTIONS.length}`;

  if (score === QUESTIONS.length) {
    emoji.textContent = "🏆";
    title.textContent = "Perfect Score!";
    message.textContent = "Outstanding! You nailed every question.";
  } else if (score >= 2) {
    emoji.textContent = "🎉";
    title.textContent = "Great Job!";
    message.textContent = "You have a solid grasp of programming languages.";
  } else if (score === 1) {
    emoji.textContent = "📚";
    title.textContent = "Keep Studying!";
    message.textContent = "You got one right — review the answers and try again.";
  } else {
    emoji.textContent = "💡";
    title.textContent = "Room to Grow!";
    message.textContent = "No worries — use the answers as a learning guide.";
  }

  panel.classList.add("visible");
  panel.scrollIntoView({ behavior: "smooth", block: "nearest" });
  panel.focus();
}

// ─── Event: Submit ─────────────────────────────────────────────────────────────
document.getElementById("quiz-form").addEventListener("submit", (e) => {
  e.preventDefault();
  if (state.submitted) return;
  state.submitted = true;

  document.getElementById("btn-submit").disabled = true;
  document.getElementById("btn-submit").textContent = "Submitted ✓";

  // Fill progress bar to 100%
  document.querySelector(".progress-bar-fill").style.width = "100%";

  const score = gradeQuiz();
  showResult(score);
});

// ─── Event: Retake ─────────────────────────────────────────────────────────────
document.getElementById("btn-retake").addEventListener("click", () => {
  state.submitted = false;
  state.selections = { q1: new Set(), q2: new Set(), q3: new Set() };

  document.getElementById("result-panel").classList.remove("visible");
  document.getElementById("btn-submit").disabled = false;
  document.getElementById("btn-submit").innerHTML = `
    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
      <polyline points="9 11 12 14 22 4"/><path d="M21 12v7a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11"/>
    </svg>
    Submit Answers`;

  document.querySelector(".progress-bar-fill").style.width = "0%";
  renderForm();
  window.scrollTo({ top: 0, behavior: "smooth" });
});

// ─── Init ─────────────────────────────────────────────────────────────────────
renderForm();
