    ],
    correct: ["q1a", "q1c"],
  },
  {
    id: "q2",
    number: "02",
    tag: "Paradigms",
    text: "Which languages primarily support functional programming as a first-class paradigm?",
    choices: [
      { id: "q2a", label: "Haskell" },
      { id: "q2b", label: "Java" },
      { id: "q2c", label: "Elixir" },
      { id: "q2d", label: "C" },
    ],
    correct: ["q2a", "q2c"],
  },
  {
    id: "q3",
    number: "03",
    tag: "History",
    text: "Which of the following languages were created in the 1970s?",
    choices: [
      { id: "q3a", label: "C" },
      { id: "q3b", label: "JavaScript" },
