};

// ─── Helpers ──────────────────────────────────────────────────────────────────
function arraysMatch(a, b) {
  return a.length === b.length && a.every((v) => b.includes(v));
}

function updateProgress() {
  const answered = QUESTIONS.filter((q) => state.selections[q.id].size > 0).length;
  const pct = (answered / QUESTIONS.length) * 100;
  document.querySelector(".progress-bar-fill").style.width = pct + "%";
}

// ─── Render ───────────────────────────────────────────────────────────────────
function renderQuestion(q) {
  const fieldEl = document.createElement("div");
  fieldEl.className = "form-field";
  fieldEl.setAttribute("role", "group");
  fieldEl.setAttribute("aria-labelledby", `${q.id}-label`);

  const meta = document.createElement("div");
  meta.className = "question-meta";
  meta.innerHTML = `<span class="question-number">${q.number}</span><span class="question-tag">${q.tag}</span>`;

  const questionText = document.createElement("p");
  questionText.className = "question-text";
  questionText.id = `${q.id}-label`;
  questionText.textContent = q.text;

  fieldEl.appendChild(meta);
  fieldEl.appendChild(questionText);

  if (q.helpText) {
    const help = document.createElement("p");
    help.className = "help-text";
    help.id = `${q.id}-help`;
    help.textContent = q.helpText;
    fieldEl.appendChild(help);
    fieldEl.setAttribute("aria-describedby", `${q.id}-help`);
  }

  const choiceList = document.createElement("div");
  choiceList.className = "choices";
  choiceList.setAttribute("role", "group");

  q.choices.forEach((choice) => {
    const label = document.createElement("label");
    label.className = "choice-label";
    label.htmlFor = choice.id;

    const checkbox = document.createElement("input");
    checkbox.type = "checkbox";
    checkbox.className = "choice-checkbox";
    checkbox.id = choice.id;
    checkbox.name = q.id;
    checkbox.value = choice.id;
    checkbox.setAttribute("aria-label", choice.label);

    checkbox.addEventListener("change", () => {
      if (state.submitted) return;
      if (checkbox.checked) {
        state.selections[q.id].add(choice.id);
      } else {
        state.selections[q.id].delete(choice.id);
      }
      updateProgress();
    });

    const text = document.createElement("span");
    text.className = "choice-text";
    text.textContent = choice.label;

    label.appendChild(checkbox);
    label.appendChild(text);
    choiceList.appendChild(label);
  });

  fieldEl.appendChild(choiceList);
  return fieldEl;
}

function renderForm() {
  const form = document.querySelector(".quiz-form");
  const questionContainer = document.getElementById("question-container");
  questionContainer.innerHTML = "";

  QUESTIONS.forEach((q) => {
    questionContainer.appendChild(renderQuestion(q));
  });
}

