function gradeQuiz() {
  let score = 0;
  QUESTIONS.forEach((q) => {
    const selected = Array.from(state.selections[q.id]);
    const isCorrect = arraysMatch(selected, q.correct);
    if (isCorrect) score++;

    const field = document.querySelector(`[aria-labelledby="${q.id}-label"]`);
    field.classList.add(isCorrect ? "correct" : "incorrect");

    // Disable all checkboxes
    field.querySelectorAll("input[type=checkbox]").forEach((cb) => {
      cb.disabled = true;
    });

    // Show feedback badge
    const badge = document.createElement("div");
    badge.className = `feedback-badge ${isCorrect ? "correct" : "incorrect"}`;
    badge.setAttribute("role", "status");
