  const panel = document.getElementById("result-panel");
  const emoji = panel.querySelector(".result-emoji");
  const title = panel.querySelector(".result-title");
  const message = panel.querySelector(".result-message");
  const scoreNum = panel.querySelector(".score-number");

  scoreNum.textContent = `${score}/${QUESTIONS.length}`;

  if (score === QUESTIONS.length) {
    emoji.textContent = "🏆";
    title.textContent = "Perfect Score!";
    message.textContent = "Outstanding! You nailed every question.";
  } else if (score >= 2) {
    emoji.textContent = "🎉";
    title.textContent = "Great Job!";
    message.textContent = "You have a solid grasp of programming languages.";
  } else if (score === 1) {
    emoji.textContent = "📚";
    title.textContent = "Keep Studying!";
    message.textContent = "You got one right — review the answers and try again.";
  } else {
    emoji.textContent = "💡";
    title.textContent = "Room to Grow!";
    message.textContent = "No worries — use the answers as a learning guide.";
  }

  panel.classList.add("visible");
  panel.scrollIntoView({ behavior: "smooth", block: "nearest" });
  panel.focus();
}

// ─── Event: Submit ─────────────────────────────────────────────────────────────
document.getElementById("quiz-form").addEventListener("submit", (e) => {
  e.preventDefault();
  if (state.submitted) return;
  state.submitted = true;

  document.getElementById("btn-submit").disabled = true;
  document.getElementById("btn-submit").textContent = "Submitted ✓";

  // Fill progress bar to 100%
  document.querySelector(".progress-bar-fill").style.width = "100%";

  const score = gradeQuiz();
  showResult(score);
});

