      <polyline points="9 11 12 14 22 4"/><path d="M21 12v7a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11"/>
    </svg>
    Submit Answers`;

  document.querySelector(".progress-bar-fill").style.width = "0%";
  renderForm();
  window.scrollTo({ top: 0, behavior: "smooth" });
});

// ─── Init ─────────────────────────────────────────────────────────────────────
renderForm();

